import{_ as t,o as a,c as s,ax as n}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Secrets and Variables","description":"Named key-value pairs — Secrets (masked credentials) and Variables (plain-text config) — referenced from connector configuration via get_secret()/get_variable()","frontmatter":{"description":"Named key-value pairs — Secrets (masked credentials) and Variables (plain-text config) — referenced from connector configuration via get_secret()/get_variable()"},"headers":[],"relativePath":"connectors/secrets/index.md","filePath":"connectors/secrets/index.md"}'),i={name:"connectors/secrets/index.md"};function r(o,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/connectors/secrets.md for this page in Markdown format</div><h1 id="secrets-and-variables" tabindex="-1">Secrets and Variables <a class="header-anchor" href="#secrets-and-variables" aria-label="Permalink to &quot;Secrets and Variables&quot;">​</a></h1><p><strong>Secrets</strong> and <strong>Variables</strong> are named key-value pairs you store once and reference from any connector. A <strong>Secret</strong> holds a sensitive value — an API key, token, or password — and is masked in the UI. A <strong>Variable</strong> holds a non-sensitive, plain-text value — a base URL, environment ID, or instance ID — and stays visible so you can see exactly what a connector uses.</p><p>Secrets and Variables are managed in <strong>Integrations</strong> → <strong>Developer Studio</strong> → <strong>Secrets and Variables</strong>, where you can create, edit, and delete both.</p><h2 id="choosing-between-a-secret-and-a-variable" tabindex="-1">Choosing between a Secret and a Variable <a class="header-anchor" href="#choosing-between-a-secret-and-a-variable" aria-label="Permalink to &quot;Choosing between a Secret and a Variable&quot;">​</a></h2><p>Choose the type when you add a value. The choice controls how the value is shown and where it can be used.</p><table tabindex="0"><thead><tr><th></th><th>Secret</th><th>Variable</th></tr></thead><tbody><tr><td>Use it for</td><td>Sensitive credentials — API keys, tokens, passwords</td><td>Non-sensitive config — base URLs, environment IDs, instance IDs</td></tr><tr><td>Shown in the UI</td><td>Masked</td><td>Visible in full</td></tr><tr><td>Reference with</td><td><code>get_secret(&#39;name&#39;)</code></td><td><code>get_variable(&#39;name&#39;)</code></td></tr><tr><td>Allowed in the connector <strong>URL</strong></td><td>No</td><td><strong>Yes</strong></td></tr><tr><td>Available in headers, query parameters, and authentication</td><td>Yes</td><td>Yes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Variables are visible — never store credentials in them</p><p>A Variable&#39;s value is plain text and shown in full in the UI. Use Variables only for non-sensitive configuration. For any credential — an API key, token, or password — always use a Secret.</p></div><p>Both are scoped to your community and resolved on the server when a connector executes, so a Variable used in a URL is applied server-side and cannot be tampered with by the browser.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>Secrets store sensitive values that must never be exposed. Their values are encrypted, masked in the UI — only the first character is shown — and never returned to the browser.</p><h3 id="referencing-secrets-in-connectors" tabindex="-1">Referencing secrets in connectors <a class="header-anchor" href="#referencing-secrets-in-connectors" aria-label="Permalink to &quot;Referencing secrets in connectors&quot;">​</a></h3><p>Use the <code>get_secret()</code> function in a template expression to reference a stored secret:</p><div class="language-jinja2 vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja2</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">get_secret</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;secret_name&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The expression is replaced with the actual secret value when the connector executes. The value is resolved on the server and never exposed to the browser.</p><h4 id="where-get-secret-is-available" tabindex="-1">Where get_secret() is available <a class="header-anchor" href="#where-get-secret-is-available" aria-label="Permalink to &quot;Where get_secret() is available&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Available</th><th>Why</th></tr></thead><tbody><tr><td>Authentication config</td><td><strong>Yes</strong></td><td>Auth values are used only in outgoing requests</td></tr><tr><td>Headers</td><td><strong>Yes</strong></td><td>Request headers are server-side only</td></tr><tr><td>Query Parameters</td><td><strong>Yes</strong></td><td>Request params are server-side only</td></tr><tr><td>URL template</td><td><strong>No</strong></td><td>Secrets stripped to prevent URLs with embedded tokens</td></tr><tr><td>Request payload</td><td><strong>No</strong></td><td>Payload forwarded to upstream API</td></tr><tr><td>Response transform</td><td><strong>No</strong></td><td>Response returned to browser, secrets excluded for safety</td></tr></tbody></table><p><strong>Key principle:</strong> Secrets resolve only in fields that control the <strong>outgoing request to the external API</strong> — authentication, headers, and query parameters. They do not resolve in fields that may leak data (URL, request bodies, response bodies) to prevent accidental exposure of credentials.</p><p><strong>Security note on URLs:</strong> Never embed <code>{{ get_secret(&#39;...&#39;) }}</code> in the URL template. Secrets are removed before the URL is built, so the reference is left unresolved and the connector fails to execute — and any token placed in a URL would be logged and could appear in browser history. Use the authentication config, headers, or query parameters instead. If you need a <strong>non-sensitive</strong> value in the URL — such as a per-environment host — use a <a href="#variables">Variable</a>.</p><p>To send a Bearer token, use the <strong>Authentication</strong> config or a custom <strong>Header</strong> — not the URL:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;api_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer {{ get_secret(&#39;my_token&#39;) }}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;header&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>This keeps the token out of URLs, logs, and browser history.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><p>Variables store non-sensitive, reusable configuration values — base URLs, environment identifiers, instance IDs. Their values stay visible in the UI, so you can confirm exactly what a connector will call.</p><p>Variables make connectors <strong>environment-aware</strong>. Store a value once under a descriptive name — such as <code>salesforce_instance_url</code> or <code>api_environment</code> — then reference that name from a connector instead of hardcoding the value. A community used for development can point at a sandbox host while production points at a live host, by changing one Variable rather than the connector.</p><h3 id="referencing-variables-in-connectors" tabindex="-1">Referencing variables in connectors <a class="header-anchor" href="#referencing-variables-in-connectors" aria-label="Permalink to &quot;Referencing variables in connectors&quot;">​</a></h3><p>Use the <code>get_variable()</code> function in a template expression:</p><div class="language-jinja2 vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja2</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">get_variable</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;variable_name&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Unlike secrets, variables also resolve inside the <strong>URL</strong> field, so you can parameterize a connector&#39;s host or path per environment. Store the full base URL as the variable&#39;s value — for example, set <code>salesforce_instance_url</code> to <code>https://acme.my.salesforce.com</code> — then build the rest of the path around it:</p><div class="language-jinja2 vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja2</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">get_variable</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;salesforce_instance_url&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/services/data/v59.0/query</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The value is resolved on the server when the connector executes.</p><h4 id="where-get-variable-is-available" tabindex="-1">Where get_variable() is available <a class="header-anchor" href="#where-get-variable-is-available" aria-label="Permalink to &quot;Where get_variable() is available&quot;">​</a></h4><p>In a standard connector, <code>get_variable()</code> resolves everywhere <code>get_secret()</code> does — authentication, headers, and query parameters — <strong>and additionally in the URL template</strong>. It does not resolve in a standard connector&#39;s request payload or response transformation templates.</p><table tabindex="0"><thead><tr><th>Field</th><th>Available</th><th>Why</th></tr></thead><tbody><tr><td>Authentication config</td><td><strong>Yes</strong></td><td>Resolved server-side in outgoing requests</td></tr><tr><td>Headers</td><td><strong>Yes</strong></td><td>Request headers are server-side only</td></tr><tr><td>Query Parameters</td><td><strong>Yes</strong></td><td>Request params are server-side only</td></tr><tr><td>URL template</td><td><strong>Yes</strong></td><td>Variables are non-sensitive, so they are kept when the URL is built</td></tr><tr><td>Request payload</td><td><strong>No</strong></td><td>Not available in a standard connector&#39;s request template</td></tr><tr><td>Response transform</td><td><strong>No</strong></td><td>Not available in a standard connector&#39;s response template</td></tr></tbody></table><p>In <a href="./../composite-connectors.html">composite connector</a> steps, <code>get_variable()</code> is available in <strong>every</strong> step template — including the request body and response body — because all step templates share one context. See <a href="./../composite-connector-reference.html#available-in-step-templates">Composite Connector Reference</a>.</p><h2 id="naming-rules" tabindex="-1">Naming rules <a class="header-anchor" href="#naming-rules" aria-label="Permalink to &quot;Naming rules&quot;">​</a></h2><p>Secret and variable names must be valid identifiers — letters, numbers, and underscores only. Names are case-sensitive.</p><p><strong>Valid names:</strong></p><ul><li><code>salesforce_instance_url</code></li><li><code>api_environment</code></li><li><code>oauth_client_id</code></li><li><code>weather_api_key</code></li></ul><p><strong>Invalid names (rejected on save):</strong></p><ul><li><code>instance-url</code> (contains hyphen)</li><li><code>api key</code> (contains space)</li><li><code>123env</code> (starts with number)</li><li><code>api@key</code> (contains special character)</li></ul><p>Use descriptive names that include the service and purpose: <code>salesforce_instance_url</code>, <code>helpdesk_subdomain</code>, <code>stripe_webhook_secret</code>.</p><p>A name cannot be used for both a Secret and a Variable in the same community — each name is unique across both.</p><p>For diagnosing values that fail to resolve, validation errors when saving, or other issues, see <a href="./../testing-and-debugging.html#secrets-and-variables-issues">Testing &amp; Debugging</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./../authentication.html">Authentication</a> — Use secrets in API Key, OAuth, and JWT authentication</li><li><a href="./../template-variables.html">Template Variables</a> — Full reference of variables and functions available in templates</li><li><a href="./../testing-and-debugging.html">Testing &amp; Debugging</a> — Verify secrets and variables resolve correctly</li></ul>`,46)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
